<script lang="ts">
  export let language = 'en';
  export let exportLanguage = 'en';
  export let roster: any[] = [];
  export let aliases: any[] = [];
  export let rosterRevision = 0;
  export let aliasesRevision = 0;
  export let onSaved: () => void = () => {};
  let tab: 'roster'|'aliases' = 'roster';
  let filters: Record<string,string> = {};
  let sortKey = 'personId'; let descending = false;
  let selected: (number|string)[] = [];
  let form: any = null; let editing = -1; let error = '';
  let importText = ''; let preview: any = null; let importType = ''; let pasteOpen=false;
  let importBytes: number[] | null = null;
  let file: HTMLInputElement;
  const zh = () => language === 'zh-CN';
  const t = (c: string,e: string) => zh()?c:e;
  const names = (r:any) => `${r.personId} ${r.canonicalName||''} ${r.pinyin||''}`;
  const rowKey = (r:any) => tab==='roster'?r.personId:(r.id??(r.zoomName||r.alias));
  $: data = (tab==='roster'?roster:aliases).filter((x:any)=> {
    const values = tab==='roster' ? [x.personId,x.canonicalName,x.pinyin,x.group,x.active===false?'no 否 停用':'yes 是 启用'] : [x.zoomName||x.alias,x.personId,roster.find((p:any)=>p.personId===x.personId)?.canonicalName,x.notes,x.lastUsedAt||'Unused'];
    return values.every((v:any,i:number)=>!filters[String(i)]||String(v??'').toLowerCase().includes(filters[String(i)].toLowerCase()));
  }).sort((a:any,b:any)=>String(a[sortKey]??'').localeCompare(String(b[sortKey]??''),undefined,{numeric:true})*(descending?-1:1));
  async function save(key:string,value:any,revision:number){const r=await fetch(`/api/config/${key}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({revision,value})});if(!r.ok){const j=await r.json().catch(()=>({}));throw Error(j.message||j.error||`${r.status}`)}onSaved()}
  function open(item?:any,index=-1){editing=index;form=item?{...item}:{...(tab==='roster'?{canonicalName:'',pinyin:'',group:'',active:true}:{zoomName:'',personId:'',notes:''})};error='';}
  async function submit(){try{const key=tab;const rows=[...(key==='roster'?roster:aliases)];if(key==='roster'){form.canonicalName=form.canonicalName.trim();if(!form.canonicalName)throw Error(t('姓名不能为空','Canonical name is required'));if(!form.pinyin.trim())form.pinyin=(await (await fetch('/api/names/pinyin',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:form.canonicalName})})).json()).pinyin;form.personId=editing<0?Math.max(0,...rows.map((x:any)=>x.personId||0))+1:rows[editing].personId;form.updatedAt=new Date().toISOString();}else{form.zoomName=form.zoomName.trim();if(!form.zoomName)throw Error(t('昵称不能为空','Nickname is required'));if(!roster.some((x:any)=>Number(x.personId)===Number(form.personId)))throw Error(t('请选择花名册人员','Choose a roster person'));if(aliases.some((x:any,i:number)=>i!==editing&&(x.zoomName||x.alias).toLowerCase()===form.zoomName.toLowerCase()))throw Error(t('昵称已存在','Nickname already exists'));form.personId=Number(form.personId);}
      if(editing<0)rows.push(form);else rows[editing]=form;await save(key,rows,key==='roster'?rosterRevision:aliasesRevision);form=null;}catch(e:any){error=e.message}}
  async function remove(item:any){const isRoster=tab==='roster';const impact=isRoster?aliases.filter((a:any)=>a.personId===item.personId).length:0;if(!confirm(isRoster?t(`删除 ${item.canonicalName} 并同时删除 ${impact} 个昵称？`,`Delete ${item.canonicalName} and its ${impact} aliases?`):t(`删除昵称 ${item.zoomName}？`,`Delete nickname ${item.zoomName}?`)))return;try{if(isRoster)await save('roster',roster.filter((x:any)=>x.personId!==item.personId),rosterRevision);else await save('aliases',aliases.filter((x:any)=>x!==item),aliasesRevision)}catch(e:any){error=e.message}}
  async function bulkEdit(){const group=tab==='roster'?prompt(t('新分组（留空保持不变）','New group (blank keeps current)')):null;const active=tab==='roster'?prompt(t('启用状态 yes/no（留空保持不变）','Active yes/no (blank keeps current)')):null;const person=tab==='aliases'?prompt(t('输入人员 ID','Enter person ID')):null;const notes=tab==='aliases'?prompt(t('新备注（留空保持不变）','New notes (blank keeps current)')):null;let rows=(tab==='roster'?roster:aliases).map((x:any)=>{if(!selected.includes(rowKey(x)))return x;if(tab==='roster')return {...x,...(group?{group}:{}),...(active?{active:['yes','是','true','1','启用'].includes(active.toLowerCase())}:{})};return {...x,...(person?{personId:Number(person)}:{}),...(notes?{notes}:{})}});try{await save(tab,rows,tab==='roster'?rosterRevision:aliasesRevision)}catch(e:any){error=e.message}}
  async function bulkDelete(){if(!selected.length||!confirm(t(`删除所选 ${selected.length} 项？`,`Delete ${selected.length} selected items?`)))return;try{if(tab==='roster')await save('roster',roster.filter((x:any)=>!selected.includes(x.personId)),rosterRevision);else await save('aliases',aliases.filter((x:any)=>!selected.includes(rowKey(x))),aliasesRevision);selected=[]}catch(e:any){error=e.message}}
  function exportCsv(ids:(number|string)[]=[]){const lang=exportLanguage==='zh'?'zh':'en';const url=`/api/config/${tab}/export?language=${lang}${ids.length?`&selected=${encodeURIComponent(ids.join('|'))}`:''}`;const a=document.createElement('a');a.href=url;a.download='';a.click()}
  async function previewImport(){try{const r=await fetch(`/api/config/${importType}/import/preview`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(importBytes?{csvBytes:importBytes}:{csv:importText})});preview=await r.json();if(!r.ok)throw Error(preview.message||'Preview failed')}catch(e:any){error=e.message}}
  async function commitImport(){try{const r=await fetch(`/api/config/${importType}/import/commit`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({revision:preview.revision,value:preview.value,changes:preview.changes})});if(!r.ok)throw Error((await r.json()).message||'Import failed');preview=null;importText='';importBytes=null;pasteOpen=false;onSaved()}catch(e:any){error=e.message}}
  async function readFile(e:Event){const f=(e.target as HTMLInputElement).files?.[0];if(f){importBytes=Array.from(new Uint8Array(await f.arrayBuffer()));importText=new TextDecoder('utf-8').decode(new Uint8Array(importBytes));pasteOpen=true;} (e.target as HTMLInputElement).value=''}
</script>

<section class="panel config-workspace">
  <div class="panel-title"><div><h2>{t('花名册与名称匹配','Roster and name matching')}</h2><p>{t('按姓名和拼音筛选，支持批量维护与 CSV 导入导出。','Filter by name and pinyin, with bulk actions and CSV import/export.')}</p></div><div class="actions"><button class="primary" onclick={()=>open()}>＋ {t('新增','Add')}</button><button onclick={()=>{importType=tab;importText='';importBytes=null;preview=null;pasteOpen=false;file?.click()}}>{t('导入 CSV','Import CSV')}</button><button onclick={()=>{importType=tab;importText='';importBytes=null;preview=null;pasteOpen=true}}>{t('粘贴 CSV','Paste CSV')}</button><button onclick={()=>exportCsv()}>{t('导出全部','Export all')}</button><input bind:this={file} type="file" accept=".csv,text/csv" hidden onchange={readFile}/></div></div>
  <div class="config-tabs"><button class:chosen={tab==='roster'} onclick={()=>{tab='roster';selected=[]}}>{t('花名册','Roster')} ({roster.length})</button><button class:chosen={tab==='aliases'} onclick={()=>{tab='aliases';selected=[]}}>{t('名称匹配','Name matching')} ({aliases.length})</button></div>
  <div class="toolbar"><button onclick={()=>selected=data.map((x:any)=>rowKey(x))}>{t('全选筛选结果','Select all filtered')}</button><button onclick={bulkEdit} disabled={!selected.length}>{t('批量编辑','Bulk edit')}</button><button class="danger" onclick={bulkDelete} disabled={!selected.length}>{t('批量删除','Bulk delete')}</button><button onclick={()=>exportCsv(selected)} disabled={!selected.length}>{t('导出所选','Export selected')}</button><button onclick={()=>selected=[]} disabled={!selected.length}>{t('退出选择','Exit selection')}</button><span>{selected.length} selected</span></div>
  {#if error}<p class="error">{error}</p>{/if}
  <div class="table-wrap"><table><thead><tr><th></th>{#each (tab==='roster'?['ID','Canonical Name','Pinyin','Group','Active']:['Nickname','ID','Canonical Name','Notes','Last Used']) as h,i}<th><button class="sort" onclick={()=>{sortKey=tab==='roster'?['personId','canonicalName','pinyin','group','active'][i]:['zoomName','personId','personId','notes','lastUsedAt'][i];descending=!descending}}>{t(({ID:'编号','Canonical Name':'姓名',Pinyin:'拼音',Group:'分组',Active:'启用',Nickname:'昵称',Notes:'备注','Last Used':'最后使用'})[h]||h,h)} ⇅</button><input class="col-filter" placeholder={t('筛选','Filter')} bind:value={filters[String(i)]}/></th>{/each}<th></th></tr></thead><tbody>{#each data as item}<tr><td><input type="checkbox" checked={selected.includes(rowKey(item))} onchange={(e)=>selected=e.currentTarget.checked?[...selected,rowKey(item)]:selected.filter((x)=>x!==rowKey(item))}/></td>{#if tab==='roster'}<td>{item.personId}</td><td title={item.canonicalName}>{item.canonicalName}</td><td>{item.pinyin||'—'}</td><td>{item.group||t('未分组','Ungrouped')}</td><td>{item.active===false?t('否','No'):t('是','Yes')}</td>{:else}<td title={item.zoomName||item.alias}>{item.zoomName||item.alias}</td><td>{item.personId}</td><td>{roster.find((p:any)=>p.personId===item.personId)?.canonicalName||'—'}</td><td>{item.notes||'—'}</td><td>{item.lastUsedAt||t('未使用','Unused')}</td>{/if}<td><button onclick={()=>open(item,(tab==='roster'?roster:aliases).indexOf(item))}>{t('编辑','Edit')}</button> <button class="danger" onclick={()=>remove(item)}>{t('删除','Delete')}</button></td></tr>{:else}<tr><td colspan="7" class="empty">{t('暂无数据','No data')}</td></tr>{/each}</tbody></table></div>
</section>
{#if form}<div class="overlay"><section class="slide-panel"><button class="close" onclick={()=>form=null}>×</button><h2>{editing<0?t('新增','Add'):t('编辑','Edit')} {tab==='roster'?t('花名册人员','roster person'):t('名称匹配','nickname mapping')}</h2>{#if tab==='roster'}{#if editing>=0}<label>ID<input value={form.personId} readonly/></label>{/if}<label>{t('姓名','Canonical name')} *<input bind:value={form.canonicalName}/></label><label>{t('拼音','Pinyin')}<input bind:value={form.pinyin} placeholder={t('留空自动生成','Auto-generated when blank')}/></label><label>{t('分组','Group')}<input bind:value={form.group}/></label><label class="check"><input type="checkbox" bind:checked={form.active}/> {t('启用','Active')}</label>{:else}<label>{t('昵称','Nickname')} *<input bind:value={form.zoomName}/></label><label>{t('花名册人员','Roster person')} *<input list="roster-options" bind:value={form.personId}/><datalist id="roster-options">{#each roster as p}<option value={p.personId}>{p.canonicalName} · {p.pinyin}</option>{/each}</datalist></label><label>{t('备注','Notes')}<textarea bind:value={form.notes}></textarea></label>{/if}{#if error}<p class="error">{error}</p>{/if}<div class="actions"><button class="primary" onclick={submit}>{t('保存','Save')}</button><button onclick={()=>form=null}>{t('取消','Cancel')}</button>{#if editing>=0}<button class="danger" onclick={()=>remove(form)}>{t('删除','Delete')}</button>{/if}</div></section></div>{/if}
{#if !preview && pasteOpen}<div class="overlay"><section class="slide-panel import-panel"><h2>{t('CSV 导入预览','CSV import preview')}</h2><textarea bind:value={importText} oninput={()=>importBytes=null} placeholder={t('粘贴 CSV 内容…','Paste CSV content…')}></textarea><div class="actions"><button class="primary" onclick={previewImport}>{t('生成预览','Preview')}</button><button onclick={()=>{importText='';importBytes=null}}>{t('清除','Clear')}</button><button onclick={()=>{importText='';importBytes=null;pasteOpen=false}}>{t('关闭','Close')}</button></div></section></div>{/if}
{#if preview}<div class="overlay"><section class="slide-panel import-panel"><h2>{t('导入预览','Import preview')}</h2><div class="table-wrap"><table><thead><tr>{#each ['row','action','id','before','after','notes','aliasImpact'] as h}<th>{h}</th>{/each}</tr></thead><tbody>{#each preview.changes||[] as c}<tr><td>{c.row}</td><td>{c.action}</td><td>{c.id}</td><td>{JSON.stringify(c.before)}</td><td>{JSON.stringify(c.after)}</td><td>{c.notes}</td><td>{c.aliasImpact||0}</td></tr>{/each}</tbody></table></div>{#if error}<p class="error">{error}</p>{/if}<div class="actions"><button class="primary" onclick={commitImport}>{t('确认导入','Commit import')}</button><button onclick={()=>preview=null}>{t('返回','Back')}</button></div></section></div>{/if}

<style>
 .config-workspace{padding:20px}.actions{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.config-tabs{display:flex;gap:6px;margin:12px 0}.config-tabs button{border:0;border-radius:7px;padding:9px 14px;background:#f1f3f6;color:#626b78}.config-tabs button.chosen{background:#eaf1ff;color:#2563eb}.toolbar{flex-wrap:wrap}.sort{border:0;background:transparent;color:inherit;padding:0;cursor:pointer}.col-filter{display:block;width:100%;min-width:60px;margin-top:7px;border:1px solid #e2e5ea;border-radius:5px;padding:5px}.overlay{position:fixed;inset:0;background:#17203366;display:flex;justify-content:flex-end;z-index:5}.slide-panel{height:100%;width:min(440px,95vw);overflow:auto;background:white;padding:28px;box-shadow:-8px 0 28px #17203322}.slide-panel h2{font-size:18px;margin:12px 0 22px}.slide-panel label{display:grid;gap:6px;margin:15px 0;font-size:12px;color:#555e6b}.slide-panel input:not([type=checkbox]),.slide-panel textarea{width:100%;padding:10px;border:1px solid #dce0e7;border-radius:7px}.slide-panel label.check{display:flex;align-items:center}.close{float:right;border:0;background:transparent;font-size:24px}.danger{color:#b83333}.error{color:#b42318}.import-panel{width:min(960px,96vw)}.import-panel textarea{width:100%;height:180px;margin:10px 0;padding:12px;border:1px solid #dce0e7;border-radius:7px}
</style>
